{"command": "mkdir -p /testbed/test/lib/util && cat > /testbed/test/lib/util/cache.test.js <<'EOF'
'use strict'

const { describe, test, expect } = require('@jest/globals')

const {
  getInterceptorOrigin,
  getRequestOrigin,
  makeCacheKey,
  normalizeHeaders,
  assertCacheKey,
  assertCacheValue,
  parseCacheControlHeader,
  hasInvalidCacheControlDirective,
  parseVaryHeader,
  hasVaryStar,
  isInvalidOrWildcardVaryHeader,
  isEtagUsable,
  assertCacheMethods,
  assertCacheStore,
  makeDeduplicationKey
} = require('../../../lib/util/cache')

const { kRequestOrigin } = require('../../../lib/core/symbols')

describe('getRequestOrigin', () => {
  test('returns a string origin as-is', () => {
    expect(getRequestOrigin({ origin: 'http://example.com' })).toBe('http://example.com')
  })

  test('returns a URL origin unchanged', () => {
    const origin = new URL('https://example.com:8443/base')
    expect(getRequestOrigin({ origin })).toBe(origin)
  })

  test('returns null when origin is missing', () => {
    expect(getRequestOrigin({})).toBeNull()
  })

  test('returns null when origin is not a string or URL', () => {
    expect(getRequestOrigin({ origin: 42 })).toBeNull()
    expect(getRequestOrigin({ origin: { href: 'http://example.com' } })).toBeNull()
    expect(getRequestOrigin({ origin: null })).toBeNull()
  })

  test('prefers the internal request origin symbol over opts.origin', () => {
    const opts = {
      origin: 'http://original.example',
      [kRequestOrigin]: 'http://resolved.example'
    }
    expect(getRequestOrigin(opts)).toBe('http://resolved.example')
  })

  test('falls back to opts.origin when the symbol is undefined', () => {
    const opts = { origin: 'http://original.example', [kRequestOrigin]: undefined }
    expect(getRequestOrigin(opts)).toBe('http://original.example')
  })
})

describe('getInterceptorOrigin', () => {
  test('returns the request origin when no interceptor origin is configured', () => {
    expect(getInterceptorOrigin({ origin: 'http://example.com' }, undefined)).toBe('http://example.com')
  })

  test('returns null when the interceptor is explicitly restricted to null', () => {
    expect(getInterceptorOrigin({ origin: 'http://example.com' }, null)).toBeNull()
  })

  test('returns the interceptor origin when the request has no usable origin', () => {
    expect(getInterceptorOrigin({}, 'http://interceptor.example')).toBe('http://interceptor.example')
    expect(getInterceptorOrigin({ origin: 17 }, 'http://interceptor.example')).toBe('http://interceptor.example')
  })

  test('returns the interceptor origin when request and interceptor origins match', () => {
    expect(getInterceptorOrigin({ origin: 'http://example.com' }, 'http://example.com')).toBe('http://example.com')
    expect(getInterceptorOrigin({ origin: new URL('http://example.com/path?q=1') }, 'http://example.com'))
      .toBe('http://example.com')
  })

  test('returns null when request and interceptor origins differ', () => {
    expect(getInterceptorOrigin({ origin: 'http://example.com' }, 'http://other.example')).toBeNull()
    expect(getInterceptorOrigin({ origin: 'https://example.com' }, 'http://example.com')).toBeNull()
  })

  test('returns the interceptor origin when the request origin cannot be parsed as a URL', () => {
    expect(getInterceptorOrigin({ origin: 'not a url' }, 'http://interceptor.example'))
      .toBe('http://interceptor.example')
  })

  test('compares against the resolved internal request origin', () => {
    const opts = {
      origin: 'http://a.example',
      [kRequestOrigin]: 'http://b.example'
    }
    expect(getInterceptorOrigin(opts, 'http://a.example')).toBeNull()
    expect(getInterceptorOrigin(opts, 'http://b.example')).toBe('http://b.example')
  })
})

describe('makeCacheKey', () => {
  test('builds a key with a default path of /', () => {
    expect(makeCacheKey({ origin: 'http://example.com', method: 'GET' })).toEqual({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: undefined
    })
  })

  test('stringifies URL origins and keeps headers', () => {
    const headers = { accept: 'text/plain' }
    expect(makeCacheKey({
      origin: new URL('http://example.com:8080/base'),
      method: 'HEAD',
      path: '/resource',
      headers
    })).toEqual({
      origin: 'http://example.com:8080',
      method: 'HEAD',
      path: '/resource',
      headers
    })
  })

  test('appends serialized query parameters when the path has none', () => {
    expect(makeCacheKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/search',
      query: { b: '2', a: '1' }
    }).path).toBe('/search?a=1&b=2')
  })

  test('serializes repeated query parameter values', () => {
    expect(makeCacheKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/search',
      query: { a: ['1', '2'] }
    }).path).toBe('/search?a=1&a=2')
  })

  test('leaves the path untouched when query is empty', () => {
    expect(makeCacheKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/search',
      query: {}
    }).path).toBe('/search')
  })

  test('leaves paths that already contain a query string untouched', () => {
    expect(makeCacheKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/search?q=1',
      query: { a: '2' }
    }).path).toBe('/search?q=1')
  })

  test('leaves paths that already contain a fragment untouched', () => {
    expect(makeCacheKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/search#frag',
      query: { a: '2' }
    }).path).toBe('/search#frag')
  })

  test('throws when no origin can be determined', () => {
    expect(() => makeCacheKey({ method: 'GET' })).toThrow('opts.origin is undefined')
    expect(() => makeCacheKey({ method: 'GET' }, null)).toThrow('opts.origin is undefined')
  })

  test('uses an explicitly provided origin', () => {
    expect(makeCacheKey({ origin: 'http://ignored.example', method: 'GET' }, 'http://explicit.example').origin)
      .toBe('http://explicit.example')
  })
})

describe('normalizeHeaders', () => {
  test('returns an empty object when headers are missing', () => {
    expect(normalizeHeaders({})).toEqual({})
    expect(normalizeHeaders({ headers: null })).toEqual({})
    expect(normalizeHeaders({ headers: undefined })).toEqual({})
  })

  test('lowercases header names from a plain object', () => {
    expect(normalizeHeaders({ headers: { 'Content-Type': 'text/plain', 'X-Custom': 'v' } }))
      .toEqual({ 'content-type': 'text/plain', 'x-custom': 'v' })
  })

  test('copies array header values so the input is not aliased', () => {
    const input = { 'x-custom': ['a', 'b'] }
    const result = normalizeHeaders({ headers: input })
    expect(result['x-custom']).toEqual(['a', 'b'])
    expect(result['x-custom']).not.toBe(input['x-custom'])
  })

  test('combines duplicate names that differ only by case', () => {
    expect(normalizeHeaders({ headers: { 'X-Custom': 'a', 'x-custom': 'b' } }))
      .toEqual({ 'x-custom': ['a', 'b'] })
  })

  test('accepts a Map of headers and merges duplicates', () => {
    expect(normalizeHeaders({ headers: new Map([['A', '1'], ['a', '2']]) })).toEqual({ a: ['1', '2'] })
  })

  test('accepts an array of [name, value] pairs', () => {
    expect(normalizeHeaders({ headers: [['A', '1'], ['B', '2']] })).toEqual({ a: '1', b: '2' })
    expect(normalizeHeaders({ headers: [['A', '1'], ['a', '2']] })).toEqual({ a: ['1', '2'] })
  })

  test('accepts a flat alternating array and merges duplicates', () => {
    expect(normalizeHeaders({ headers: ['a', '1', 'b', '2'] })).toEqual({ a: '1', b: '2' })
    expect(normalizeHeaders({ headers: ['a', '1', 'A', '2'] })).toEqual({ a: ['1', '2'] })
  })

  test('expands array values in a flat alternating array', () => {
    expect(normalizeHeaders({ headers: ['a', ['1', '2']] })).toEqual({ a: ['1', '2'] })
  })

  test('converts Buffer values in a flat alternating array using latin1', () => {
    expect(normalizeHeaders({ headers: ['a', [Buffer.from('héllo', 'latin1'), 'plain']] }))
      .toEqual({ a: ['héllo', 'plain'] })
  })

  test('rejects non-object headers', () => {
    expect(() => normalizeHeaders({ headers: 'a=b' })).toThrow('opts.headers is not an object')
    expect(() => normalizeHeaders({ headers: 42 })).toThrow('opts.headers is not an object')
  })

  test('rejects a flat alternating array with an odd number of entries', () => {
    expect(() => normalizeHeaders({ headers: ['a', '1', 'b'] }))
      .toThrow('opts.headers is not a valid header map')
  })

  test('rejects non-string names and values in an array of pairs', () => {
    expect(() => normalizeHeaders({ headers: [['a', 1]] }))
      .toThrow('opts.headers is not a valid header map')
    expect(() => normalizeHeaders({ headers: [[1, 'a']] }))
      .toThrow('opts.headers is not a valid header map')
  })

  test('rejects mixed entry shapes in an array of pairs', () => {
    expect(() => normalizeHeaders({ headers: [['a', '1'], 'b'] }))
      .toThrow('opts.headers is not a valid header map')
  })

  test('does not pollute the prototype through a __proto__ header name', () => {
    const input = JSON.parse('{"__proto__":"evil","a":"1"}')
    const result = normalizeHeaders({ headers: input })

    expect(Object.hasOwn(result, '__proto__')).toBe(true)
    expect(result['__proto__']).toBe('evil')
    expect(Object.getPrototypeOf(result)).toBe(Object.prototype)
    expect(({}).evil).toBeUndefined()
  })
})

describe('assertCacheKey', () => {
  test('accepts a well formed cache key', () => {
    expect(() => assertCacheKey({ origin: 'http://example.com', method: 'GET', path: '/', headers: {} }))
      .not.toThrow()
    expect(() => assertCacheKey({ origin: 'http://example.com', method: 'GET', path: '/' }))
      .not.toThrow()
  })

  test('rejects non-object values', () => {
    expect(() => assertCacheKey('key')).toThrow(TypeError)
    expect(() => assertCacheKey('key')).toThrow('expected key to be object, got string')
  })

  test('rejects objects missing required string properties', () => {
    expect(() => assertCacheKey({ method: 'GET', path: '/' }))
      .toThrow('expected key.origin to be string, got undefined')
    expect(() => assertCacheKey({ origin: 'http://example.com', path: '/' }))
      .toThrow('expected key.method to be string, got undefined')
    expect(() => assertCacheKey({ origin: 'http://example.com', method: 'GET' }))
      .toThrow('expected key.path to be string, got undefined')
  })

  test('rejects non-object headers', () => {
    expect(() => assertCacheKey({ origin: 'http://example.com', method: 'GET', path: '/', headers: 'a' }))
      .toThrow(TypeError)
  })
})

describe('assertCacheValue', () => {
  test('accepts a minimally valid cache value', () => {
    expect(() => assertCacheValue({
      statusCode: 200,
      statusMessage: 'OK',
      cachedAt: 1,
      staleAt: 2,
      deleteAt: 3
    })).not.toThrow()
  })

  test('accepts optional headers, vary, and etag fields', () => {
    expect(() => assertCacheValue({
      statusCode: 200,
      statusMessage: 'OK',
      headers: null,
      vary: null,
      etag: 'W/"abc"',
      cachedAt: 1,
      staleAt: 2,
      deleteAt: 3
    })).not.toThrow()
  })

  test('rejects non-object values', () => {
    expect(() => assertCacheValue(42)).toThrow(TypeError)
    expect(() => assertCacheValue(42)).toThrow('expected value to be object, got number')
  })

  test('rejects non-numeric timestamps and status codes', () => {
    const base = { statusCode: 200, statusMessage: 'OK', cachedAt: 1, staleAt: 2, deleteAt: 3 }
    expect(() => assertCacheValue({ ...base, statusCode: '200' }))
      .toThrow('expected value.statusCode to be number, got string')
    expect(() => assertCacheValue({ ...base, cachedAt: undefined }))
      .toThrow('expected value.cachedAt to be number, got undefined')
    expect(() => assertCacheValue({ ...base, staleAt: undefined }))
      .toThrow('expected value.staleAt to be number, got undefined')
    expect(() => assertCacheValue({ ...base, deleteAt: undefined }))
      .toThrow('expected value.deleteAt to be number, got undefined')
  })

  test('rejects a non-string status message', () => {
    expect(() => assertCacheValue({ statusCode: 200, cachedAt: 1, staleAt: 2, deleteAt: 3 }))
      .toThrow('expected value.statusMessage to be string, got undefined')
  })

  test('rejects non-object headers and vary fields', () => {
    const base = { statusCode: 200, statusMessage: 'OK', cachedAt: 1, staleAt: 2, deleteAt: 3 }
    expect(() => assertCacheValue({ ...base, headers: 'x' })).toThrow(TypeError)
    expect(() => assertCacheValue({ ...base, vary: 'x' }))
      .toThrow('expected value.vary to be object, got string')
  })

  test('rejects a non-string etag', () => {
    expect(() => assertCacheValue({
      statusCode: 200,
      statusMessage: 'OK',
      etag: 5,
      cachedAt: 1,
      staleAt: 2,
      deleteAt: 3
    })).toThrow('expected value.etag to be string, got number')
  })
})

describe('parseCacheControlHeader', () => {
  test('parses a single numeric directive', () => {
    expect(parseCacheControlHeader('max-age=60')).toEqual({ 'max-age': 60 })
  })

  test('parses every supported numeric directive', () => {
    expect(parseCacheControlHeader('s-maxage=30')).toEqual({ 's-maxage': 30 })
    expect(parseCacheControlHeader('min-fresh=5')).toEqual({ 'min-fresh': 5 })
    expect(parseCacheControlHeader('max-stale=15')).toEqual({ 'max-stale': 15 })
    expect(parseCacheControlHeader('stale-while-revalidate=7')).toEqual({ 'stale-while-revalidate': 7 })
    expect(parseCacheControlHeader('stale-if-error=9')).toEqual({ 'stale-if-error': 9 })
  })

  test('parses boolean directives', () => {
    expect(parseCacheControlHeader('no-store')).toEqual({ 'no-store': true })
    expect(parseCacheControlHeader('no-cache')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('private')).toEqual({ private: true })
    expect(parseCacheControlHeader('public')).toEqual({ public: true })
    expect(parseCacheControlHeader('must-revalidate')).toEqual({ 'must-revalidate': true })
    expect(parseCacheControlHeader('proxy-revalidate')).toEqual({ 'proxy-revalidate': true })
    expect(parseCacheControlHeader('immutable')).toEqual({ immutable: true })
    expect(parseCacheControlHeader('no-transform')).toEqual({ 'no-transform': true })
    expect(parseCacheControlHeader('must-understand')).toEqual({ 'must-understand': true })
    expect(parseCacheControlHeader('only-if-cached')).toEqual({ 'only-if-cached': true })
  })

  test('parses multiple directives and is case insensitive', () => {
    expect(parseCacheControlHeader('Max-Age=60, NO-STORE, Public')).toEqual({
      'max-age': 60,
      'no-store': true,
      public: true
    })
  })

  test('accepts an array of header lines', () => {
    expect(parseCacheControlHeader(['max-age=60', 'no-store'])).toEqual({ 'max-age': 60, 'no-store': true })
    expect(parseCacheControlHeader(['max-age=60, no-store'])).toEqual({ 'max-age': 60, 'no-store': true })
  })

  test('keeps the most restrictive max-age', () => {
    expect(parseCacheControlHeader('max-age=100, max-age=50')).toEqual({ 'max-age': 50 })
    expect(parseCacheControlHeader('max-age=50, max-age=100')).toEqual({ 'max-age': 50 })
  })

  test('keeps the largest min-fresh', () => {
    expect(parseCacheControlHeader('min-fresh=10, min-fresh=50')).toEqual({ 'min-fresh': 50 })
    expect(parseCacheControlHeader('min-fresh=50, min-fresh=10')).toEqual({ 'min-fresh': 50 })
  })

  test('accepts quoted numeric values', () => {
    expect(parseCacheControlHeader('max-age="60"')).toEqual({ 'max-age': 60 })
  })

  test('clamps delta seconds to the maximum 32 bit integer', () => {
    expect(parseCacheControlHeader('max-age=2147483648')).toEqual({ 'max-age': 2147483647 })
    expect(parseCacheControlHeader('max-age=99999999999999999999')).toEqual({ 'max-age': 2147483647 })
  })

  test('marks invalid numeric directives as invalid and drops them', () => {
    const directives = parseCacheControlHeader('max-age=abc')
    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('drops numeric directives without a value', () => {
    const directives = parseCacheControlHeader('max-age')
    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('a later invalid directive overrides an earlier valid one', () => {
    const directives = parseCacheControlHeader('max-age=60, max-age= 30')
    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('keeps valid directives when an unrelated directive is invalid', () => {
    const directives = parseCacheControlHeader('no-store, s-maxage=oops')
    expect(directives).toEqual({ 'no-store': true })
    expect(hasInvalidCacheControlDirective(directives, 's-maxage')).toBe(true)
    expect(hasInvalidCacheControlDirective(directives, 'no-store')).toBe(false)
  })

  test('parses a qualified no-cache field list from a quoted list', () => {
    expect(parseCacheControlHeader('no-cache="set-cookie, authorization"')).toEqual({
      'no-cache': ['set-cookie', 'authorization']
    })
  })

  test('parses a qualified no-cache with unquoted and quoted single fields', () => {
    expect(parseCacheControlHeader('no-cache=set-cookie')).toEqual({ 'no-cache': ['set-cookie'] })
    expect(parseCacheControlHeader('no-cache="set-cookie"')).toEqual({ 'no-cache': ['set-cookie'] })
  })

  test('accumulates repeated qualified no-cache directives', () => {
    expect(parseCacheControlHeader('no-cache=foo, no-cache=bar')).toEqual({ 'no-cache': ['foo', 'bar'] })
    expect(parseCacheControlHeader('no-cache="a", no-cache="b"')).toEqual({ 'no-cache': ['a', 'b'] })
  })

  test('degrades qualified directives with invalid field names to true', () => {
    expect(parseCacheControlHeader('no-cache=bad@name')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('no-cache="a b"')).toEqual({ 'no-cache': true })
  })

  test('treats an empty no-cache value as unqualified', () => {
    expect(parseCacheControlHeader('no-cache=')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('no-cache=""')).toEqual({ 'no-cache': true })
  })

  test('parses qualified private directives like no-cache', () => {
    expect(parseCacheControlHeader('private=x')).toEqual({ private: ['x'] })
    expect(parseCacheControlHeader('private="a, b", no-store')).toEqual({
      private: ['a', 'b'],
      'no-store': true
    })
  })

  test('handles a qualified directive combined with other directives', () => {
    expect(parseCacheControlHeader('max-age=60, no-cache="set-cookie"')).toEqual({
      'max-age': 60,
      'no-cache': ['set-cookie']
    })
  })

  test('degrades an unterminated quoted field list to true', () => {
    expect(parseCacheControlHeader('no-cache="a')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('no-cache="foo, max-age=10')).toEqual({ 'no-cache': true })
  })

  test('ignores numeric directives hidden inside a malformed quoted value', () => {
    expect(parseCacheControlHeader('public="x, max-age=60')).toEqual({})
  })

  test('ignores unknown directives', () => {
    expect(parseCacheControlHeader('foo=bar, unknown')).toEqual({})
  })

  test('drops no-argument directives that are given a value for every occurrence', () => {
    const directives = parseCacheControlHeader('public=x, public')
    expect(directives).toEqual({})
  })

  test('keeps no-store even when other directives are malformed', () => {
    const directives = parseCacheControlHeader('max-age="60, no-store')
    expect(directives).toEqual({ 'no-store': true })
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('recognises restrictive directives with malformed token characters', () => {
    expect(parseCacheControlHeader('no-store@x')).toEqual({ 'no-store': true })
    expect(parseCacheControlHeader('no-cache;')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('private x')).toEqual({ private: true })
  })

  test('tolerates whitespace around directives', () => {
    expect(parseCacheControlHeader(' max-age=60 , no-store ')).toEqual({ 'max-age': 60, 'no-store': true })
  })

  test('parses directives separated by an escaped quote', () => {
