describe('parseCacheControlHeader', () => {
  test('parses a single numeric directive', () => {
    expect(parseCacheControlHeader('max-age=60')).toEqual({ 'max-age': 60 })
  })

  test('parses every supported numeric directive', () => {
    expect(parseCacheControlHeader('s-maxage=30')).toEqual({ 's-maxage': 30 })
    expect(parseCacheControlHeader('min-fresh=5')).toEqual({ 'min-fresh': 5 })
    expect(parseCacheControlHeader('max-stale=15')).toEqual({ 'max-stale': 15 })
    expect(parseCacheControlHeader('stale-while-revalidate=7')).toEqual({ 'stale-while-revalidate': 7 })
    expect(parseCacheControlHeader('stale-if-error=9')).toEqual({ 'stale-if-error': 9 })
  })

  test('parses boolean directives', () => {
    expect(parseCacheControlHeader('no-store')).toEqual({ 'no-store': true })
    expect(parseCacheControlHeader('no-cache')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('private')).toEqual({ private: true })
    expect(parseCacheControlHeader('public')).toEqual({ public: true })
    expect(parseCacheControlHeader('must-revalidate')).toEqual({ 'must-revalidate': true })
    expect(parseCacheControlHeader('proxy-revalidate')).toEqual({ 'proxy-revalidate': true })
    expect(parseCacheControlHeader('immutable')).toEqual({ immutable: true })
    expect(parseCacheControlHeader('no-transform')).toEqual({ 'no-transform': true })
    expect(parseCacheControlHeader('must-understand')).toEqual({ 'must-understand': true })
    expect(parseCacheControlHeader('only-if-cached')).toEqual({ 'only-if-cached': true })
  })

  test('parses multiple directives and is case insensitive', () => {
    expect(parseCacheControlHeader('Max-Age=60, NO-STORE, Public')).toEqual({
      'max-age': 60,
      'no-store': true,
      public: true
    })
  })

  test('accepts an array of header lines', () => {
    expect(parseCacheControlHeader(['max-age=60', 'no-store'])).toEqual({ 'max-age': 60, 'no-store': true })
    expect(parseCacheControlHeader(['max-age=60, no-store'])).toEqual({ 'max-age': 60, 'no-store': true })
  })

  test('keeps the most restrictive max-age', () => {
    expect(parseCacheControlHeader('max-age=100, max-age=50')).toEqual({ 'max-age': 50 })
    expect(parseCacheControlHeader('max-age=50, max-age=100')).toEqual({ 'max-age': 50 })
  })

  test('keeps the largest min-fresh', () => {
    expect(parseCacheControlHeader('min-fresh=10, min-fresh=50')).toEqual({ 'min-fresh': 50 })
    expect(parseCacheControlHeader('min-fresh=50, min-fresh=10')).toEqual({ 'min-fresh': 50 })
  })

  test('accepts quoted numeric values', () => {
    expect(parseCacheControlHeader('max-age="60"')).toEqual({ 'max-age': 60 })
  })

  test('clamps delta seconds to the maximum 32 bit integer', () => {
    expect(parseCacheControlHeader('max-age=2147483648')).toEqual({ 'max-age': 2147483647 })
    expect(parseCacheControlHeader('max-age=99999999999999999999')).toEqual({ 'max-age': 2147483647 })
  })

  test('marks invalid numeric directives as invalid and drops them', () => {
    const directives = parseCacheControlHeader('max-age=abc')
    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('drops numeric directives without a value', () => {
    const directives = parseCacheControlHeader('max-age')
    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('a later invalid directive overrides an earlier valid one', () => {
    const directives = parseCacheControlHeader('max-age=60, max-age= 30')
    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('keeps valid directives when an unrelated directive is invalid', () => {
    const directives = parseCacheControlHeader('no-store, s-maxage=oops')
    expect(directives).toEqual({ 'no-store': true })
    expect(hasInvalidCacheControlDirective(directives, 's-maxage')).toBe(true)
    expect(hasInvalidCacheControlDirective(directives, 'no-store')).toBe(false)
  })

  test('parses a qualified no-cache field list from a quoted list', () => {
    expect(parseCacheControlHeader('no-cache="set-cookie, authorization"')).toEqual({
      'no-cache': ['set-cookie', 'authorization']
    })
  })

  test('parses a qualified no-cache with unquoted and quoted single fields', () => {
    expect(parseCacheControlHeader('no-cache=set-cookie')).toEqual({ 'no-cache': ['set-cookie'] })
    expect(parseCacheControlHeader('no-cache="set-cookie"')).toEqual({ 'no-cache': ['set-cookie'] })
  })

  test('accumulates repeated qualified no-cache directives', () => {
    expect(parseCacheControlHeader('no-cache=foo, no-cache=bar')).toEqual({ 'no-cache': ['foo', 'bar'] })
    expect(parseCacheControlHeader('no-cache="a", no-cache="b"')).toEqual({ 'no-cache': ['a', 'b'] })
  })

  test('degrades qualified directives with invalid field names to true', () => {
    expect(parseCacheControlHeader('no-cache=bad@name')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('no-cache="a b"')).toEqual({ 'no-cache': true })
  })

  test('treats an empty no-cache value as unqualified', () => {
    expect(parseCacheControlHeader('no-cache=')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('no-cache=""')).toEqual({ 'no-cache': true })
  })

  test('parses qualified private directives like no-cache', () => {
    expect(parseCacheControlHeader('private=x')).toEqual({ private: ['x'] })
    expect(parseCacheControlHeader('private="a, b", no-store')).toEqual({
      private: ['a', 'b'],
      'no-store': true
    })
  })

  test('handles a qualified directive combined with other directives', () => {
    expect(parseCacheControlHeader('max-age=60, no-cache="set-cookie"')).toEqual({
      'max-age': 60,
      'no-cache': ['set-cookie']
    })
  })

  test('degrades an unterminated quoted field list to true', () => {
    expect(parseCacheControlHeader('no-cache="a')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('no-cache="foo, max-age=10')).toEqual({ 'no-cache': true })
  })

  test('ignores numeric directives hidden inside a malformed quoted value', () => {
    expect(parseCacheControlHeader('public="x, max-age=60')).toEqual({})
  })

  test('ignores unknown directives', () => {
    expect(parseCacheControlHeader('foo=bar, unknown')).toEqual({})
  })

  test('drops no-argument directives that are given a value for every occurrence', () => {
    const directives = parseCacheControlHeader('public=x, public')
    expect(directives).toEqual({})
  })

  test('keeps no-store even when other directives are malformed', () => {
    const directives = parseCacheControlHeader('max-age="60, no-store')
    expect(directives).toEqual({ 'no-store': true })
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('recognises restrictive directives with malformed token characters', () => {
    expect(parseCacheControlHeader('no-store@x')).toEqual({ 'no-store': true })
    expect(parseCacheControlHeader('no-cache;')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('private x')).toEqual({ private: true })
  })

  test('tolerates whitespace around directives', () => {
    expect(parseCacheControlHeader(' max-age=60 , no-store ')).toEqual({ 'max-age': 60, 'no-store': true })
  })

  test('parses directives separated by an escaped quote', () => {
    expect(parseCacheControlHeader('no-cache="a\\"b", no-store')).toEqual({
      'no-cache': ['a\\"b'],
      'no-store': true
    })
  })
})

describe('hasInvalidCacheControlDirective', () => {
  test('returns false for a directive set that had no invalid entries', () => {
    expect(hasInvalidCacheControlDirective(parseCacheControlHeader('max-age=60'), 'max-age')).toBe(false)
    expect(hasInvalidCacheControlDirective(parseCacheControlHeader('no-store'), 'max-age')).toBe(false)
  })

  test('returns false for a plain object that was never parsed', () => {
    expect(hasInvalidCacheControlDirective({}, 'max-age')).toBe(false)
  })

  test('returns true only for the directive that was invalid', () => {
    const directives = parseCacheControlHeader('max-age=x, min-fresh=10')
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
    expect(hasInvalidCacheControlDirective(directives, 'min-fresh')).toBe(false)
  })
})

describe('hasVaryStar', () => {
  test('detects a wildcard vary header', () => {
    expect(hasVaryStar('*')).toBe(true)
    expect(hasVaryStar('accept-encoding, *')).toBe(true)
    expect(hasVaryStar(' * ')).toBe(true)
  })

  test('detects a wildcard inside any value of an array header', () => {
    expect(hasVaryStar(['accept-encoding', '*'])).toBe(true)
    expect(hasVaryStar(['accept-encoding', 'x*y'])).toBe(true)
  })

  test('returns false when no wildcard is present', () => {
    expect(hasVaryStar('accept-encoding')).toBe(false)
    expect(hasVaryStar('accept-encoding, accept-language')).toBe(false)
    expect(hasVaryStar([])).toBe(false)
    expect(hasVaryStar('')).toBe(false)
  })
})

describe('parseVaryHeader', () => {
  test('maps varying header names to request header values', () => {
    expect(parseVaryHeader('Accept-Encoding', { 'accept-encoding': 'gzip' })).toEqual({
      'accept-encoding': 'gzip'
    })
    expect(parseVaryHeader('accept-encoding, accept-language', {
      'accept-encoding': 'gzip',
      'accept-language': 'en'
    })).toEqual({ 'accept-encoding': 'gzip', 'accept-language': 'en' })
  })

  test('uses null for headers that are absent from the request', () => {
    expect(parseVaryHeader('accept-encoding, user-agent', { 'accept-encoding': 'gzip' })).toEqual({
      'accept-encoding': 'gzip',
      'user-agent': null
    })
  })

  test('copies array header values', () => {
    const headers = { 'accept-encoding': ['gzip', 'br'] }
    const result = parseVaryHeader('accept-encoding', headers)
    expect(result['accept-encoding']).toEqual(['gzip', 'br'])
    expect(result['accept-encoding']).not.toBe(headers['accept-encoding'])
  })

  test('returns the original headers object for a wildcard vary header', () => {
    const headers = { 'accept-encoding': 'gzip' }
    expect(parseVaryHeader('*', headers)).toBe(headers)
  })

  test('accepts an array of vary header lines', () => {
    expect(parseVaryHeader(['accept-encoding', 'accept-language'], {
      'accept-encoding': 'gzip',
      'accept-language': 'en'
    })).toEqual({ 'accept-encoding': 'gzip', 'accept-language': 'en' })
  })

  test('ignores empty entries', () => {
    expect(parseVaryHeader('', {})).toEqual({})
    expect(parseVaryHeader('accept-encoding,,', { 'accept-encoding': 'gzip' })).toEqual({
      'accept-encoding': 'gzip'
    })
  })

  test('returns undefined for invalid header names', () => {
    expect(parseVaryHeader('accept encoding', {})).toBeUndefined()
    expect(parseVaryHeader('accept-encoding, bad header', { 'accept-encoding': 'gzip' })).toBeUndefined()
  })
})

describe('isInvalidOrWildcardVaryHeader', () => {
  test('returns true for wildcard headers', () => {
    expect(isInvalidOrWildcardVaryHeader('*')).toBe(true)
    expect(isInvalidOrWildcardVaryHeader('accept-encoding, *')).toBe(true)
  })

  test('returns true for invalid header names', () => {
    expect(isInvalidOrWildcardVaryHeader('bad header')).toBe(true)
  })

  test('returns false for valid header names without a wildcard', () => {
    expect(isInvalidOrWildcardVaryHeader('accept-encoding')).toBe(false)
    expect(isInvalidOrWildcardVaryHeader('accept-encoding, accept-language')).toBe(false)
    expect(isInvalidOrWildcardVaryHeader('')).toBe(false)
  })
})

describe('isEtagUsable', () => {
  test('accepts strong and weak quoted etags', () => {
    expect(isEtagUsable('"abc"')).toBe(true)
    expect(isEtagUsable('W/"abc"')).toBe(true)
    expect(isEtagUsable('W/"ab"')).toBe(true)
  })

  test('rejects unquoted etags', () => {
    expect(isEtagUsable('abc')).toBe(false)
    expect(isEtagUsable('"abc')).toBe(false)
    expect(isEtagUsable('W/"abc')).toBe(false)
  })

  test('rejects empty etags', () => {
    expect(isEtagUsable('')).toBe(false)
    expect(isEtagUsable('""')).toBe(false)
    expect(isEtagUsable('W/""')).toBe(false)
  })

  test('rejects doubly quoted and nested weak etags', () => {
    expect(isEtagUsable('""abc""')).toBe(false)
    expect(isEtagUsable('"W/"abc""')).toBe(true === false ? true : isEtagUsable('"W/"abc""'))
    expect(isEtagUsable('"W/"abc""')).toBe(false)
  })
})

describe('assertCacheStore', () => {
  test('accepts an object implementing the store interface', () => {
    const store = {
      get () {},
      createWriteStream () {},
      delete () {}
    }
    expect(() => assertCacheStore(store)).not.toThrow()
  })

  test('rejects non-object stores', () => {
    expect(() => assertCacheStore(null)).toThrow(TypeError)
    expect(() => assertCacheStore(null))
      .toThrow('expected type of CacheStore to be a CacheStore, got null')
    expect(() => assertCacheStore('store'))
      .toThrow('expected type of CacheStore to be a CacheStore, got string')
  })

  test('requires each of the store methods', () => {
    expect(() => assertCacheStore({})).toThrow('CacheStore needs to have a `get()` function')
    expect(() => assertCacheStore({ get () {} }))
      .toThrow('CacheStore needs to have a `createWriteStream()` function')
    expect(() => assertCacheStore({ get () {}, createWriteStream () {} }))
      .toThrow('CacheStore needs to have a `delete()` function')
    expect(() => assertCacheStore({ get: 'nope', createWriteStream () {}, delete () {} }))
      .toThrow('CacheStore needs to have a `get()` function')
  })

  test('uses the provided name in error messages', () => {
    expect(() => assertCacheStore({}, 'MyStore')).toThrow('MyStore needs to have a `get()` function')
    expect(() => assertCacheStore(undefined, 'MyStore'))
      .toThrow('expected type of MyStore to be a CacheStore, got undefined')
  })
})

describe('assertCacheMethods', () => {
  test('accepts any non-empty list of safe HTTP methods', () => {
    expect(() => assertCacheMethods(['GET'])).not.toThrow()
    expect(() => assertCacheMethods(['GET', 'HEAD', 'OPTIONS', 'TRACE'])).not.toThrow()
  })

  test('rejects values that are not arrays', () => {
    expect(() => assertCacheMethods('GET')).toThrow(TypeError)
    expect(() => assertCacheMethods('GET'))
      .toThrow('expected type of CacheMethods needs to be an array, got string')
    expect(() => assertCacheMethods(null))
      .toThrow('expected type of CacheMethods needs to be an array, got null')
  })

  test('rejects an empty method list', () => {
    expect(() => assertCacheMethods([])).toThrow('CacheMethods needs to have at least one method')
  })

  test('rejects unsafe or unknown methods', () => {
    expect(() => assertCacheMethods(['POST']))
      .toThrow('element of CacheMethods-array needs to be one of following values: GET, HEAD, OPTIONS, TRACE, got POST')
    expect(() => assertCacheMethods(['get'])).toThrow(TypeError)
    expect(() => assertCacheMethods(['GET', 'DELETE'])).toThrow(TypeError)
  })

  test('uses the provided name in error messages', () => {
    expect(() => assertCacheMethods([], 'MyMethods')).toThrow('MyMethods needs to have at least one method')
    expect(() => assertCacheMethods(['POST'], 'MyMethods'))
      .toThrow('element of MyMethods-array needs to be one of following values: GET, HEAD, OPTIONS, TRACE, got POST')
  })
})

describe('makeDeduplicationKey', () => {
  test('produces a JSON encoded array of origin, method, path, and headers', () => {
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/resource'
    })
    expect(JSON.parse(key)).toEqual(['http://example.com', 'GET', '/resource', {}])
  })

  test('produces the same key regardless of header insertion order', () => {
    const a = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { b: '2', a: '1' }
    })
    const b = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: '1', b: '2' }
    })
    expect(a).toBe(b)
  })

  test('distinguishes different origins, methods, paths, and header values', () => {
    const base = { origin: 'http://example.com', method: 'GET', path: '/', headers: { a: '1' } }
    expect(makeDeduplicationKey(base)).not.toBe(makeDeduplicationKey({ ...base, origin: 'http://other.example' }))
    expect(makeDeduplicationKey(base)).not.toBe(makeDeduplicationKey({ ...base, method: 'HEAD' }))
    expect(makeDeduplicationKey(base)).not.toBe(makeDeduplicationKey({ ...base, path: '/other' }))
    expect(makeDeduplicationKey(base)).not.toBe(makeDeduplicationKey({ ...base, headers: { a: '2' } }))
  })

  test('does not collide on header values containing delimiters', () => {
    const one = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: 'x:b=y' }
    })
    const two = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: 'x', b: 'y' }
    })
    expect(one).not.toBe(two)
  })

  test('preserves array header values', () => {
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: ['1', '2'] }
    })
    expect(JSON.parse(key)[3]).toEqual({ a: ['1', '2'] })
  })

  test('omits excluded headers case-insensitively', () => {
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { 'Accept-Encoding': 'gzip', a: '1' }
    }, new Set(['accept-encoding']))
    expect(JSON.parse(key)[3]).toEqual({ a: '1' })
  })

  test('does not alter the key when the exclusion set does not match', () => {
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: '1' }
    }, new Set(['accept-encoding']))
    expect(JSON.parse(key)[3]).toEqual({ a: '1' })
  })

  test('handles a __proto__ header name without polluting the key object', () => {
    const headers = JSON.parse('{"__proto__":"evil","a":"1"}')
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers
    })
    const parsedHeaders = JSON.parse(key)[3]
    expect(Object.hasOwn(parsedHeaders, '__proto__')).toBe(true)
    expect(parsedHeaders['__proto__']).toBe('evil')
    expect(parsedHeaders.a).toBe('1')
    expect(({}).evil).toBeUndefined()
  })
})
