'use strict'

const { EventEmitter } = require('node:events')
const zlib = require('node:zlib')

const { ByteParser } = require('../../../../lib/web/websocket/receiver')
const { PerMessageDeflate } = require('../../../../lib/web/websocket/permessage-deflate')
const {
  opcodes,
  states,
  sentCloseFrameState
} = require('../../../../lib/web/websocket/constants')

function createSocket () {
  const socket = new EventEmitter()

  socket.writableNeedDrain = false
  socket.destroyed = false
  socket.writes = []
  socket.write = jest.fn((chunk) => {
    socket.writes.push(Buffer.from(chunk))
    return true
  })
  socket.destroy = jest.fn(() => {
    socket.destroyed = true
  })

  return socket
}

function createHandler (overrides = {}) {
  const socket = overrides.socket ?? createSocket()
  const handler = {
    onMessage: jest.fn(),
    onPing: jest.fn(),
    onPong: jest.fn(),
    readyState: states.OPEN,
    closeState: new Set(),
    controller: { abort: jest.fn() },
    onSocketClose: jest.fn(),
    ...overrides,
    socket
  }

  return handler
}

function createParser ({ handler: handlerOverrides, options, extensions = null } = {}) {
  const handler = createHandler(handlerOverrides)
  return {
    handler,
    socket: handler.socket,
    parser: new ByteParser(handler, extensions, options)
  }
}

function makeFrame ({
  opcode,
  payload = Buffer.alloc(0),
  fin = true,
  rsv1 = false,
  rsv2 = false,
  rsv3 = false,
  masked = false
}) {
  const body = Buffer.isBuffer(payload) ? payload : Buffer.from(payload)
  const firstByte = (fin ? 0x80 : 0) |
    (rsv1 ? 0x40 : 0) |
    (rsv2 ? 0x20 : 0) |
    (rsv3 ? 0x10 : 0) |
    opcode

  let secondByte = body.length
  let extendedLength = Buffer.alloc(0)

  if (body.length > 125 && body.length <= 0xffff) {
    secondByte = 126
    extendedLength = Buffer.allocUnsafe(2)
    extendedLength.writeUInt16BE(body.length, 0)
  } else if (body.length > 0xffff) {
    secondByte = 127
    extendedLength = Buffer.allocUnsafe(8)
    extendedLength.writeUInt32BE(0, 0)
    extendedLength.writeUInt32BE(body.length, 4)
  }

  if (masked) {
    secondByte |= 0x80
  }

  return Buffer.concat([
    Buffer.from([firstByte, secondByte]),
    extendedLength,
    body
  ])
}

function decodeFrame (frame) {
  expect(Buffer.isBuffer(frame)).toBe(true)

  const firstByte = frame[0]
  const secondByte = frame[1]
  const masked = (secondByte & 0x80) !== 0
  let payloadLength = secondByte & 0x7f
  let offset = 2

  if (payloadLength === 126) {
    payloadLength = frame.readUInt16BE(offset)
    offset += 2
  } else if (payloadLength === 127) {
    payloadLength = Number(frame.readBigUInt64BE(offset))
    offset += 8
  }

  let mask
  if (masked) {
    mask = frame.subarray(offset, offset + 4)
    offset += 4
  }

  const body = Buffer.from(frame.subarray(offset, offset + payloadLength))
  if (masked) {
    for (let i = 0; i < body.length; ++i) {
      body[i] ^= mask[i & 3]
    }
  }

  return {
    fin: (firstByte & 0x80) !== 0,
    opcode: firstByte & 0x0f,
    masked,
    body
  }
}

function expectConnectionFailure (handler, code) {
  expect(handler.controller.abort).toHaveBeenCalledTimes(1)
  expect(handler.socket.destroy).toHaveBeenCalledTimes(1)
  expect(handler.socket.destroyed).toBe(true)
  expect(handler.readyState).toBe(states.CLOSING)
  expect(handler.closeState.has(sentCloseFrameState.SENT)).toBe(true)

  const closeFrame = decodeFrame(handler.socket.writes.at(-1))
  expect(closeFrame.opcode).toBe(opcodes.CLOSE)
  expect(closeFrame.body.length).toBeGreaterThanOrEqual(2)
  expect(closeFrame.body.readUInt16BE(0)).toBe(code)
}

function closePayload (code, reason = Buffer.alloc(0)) {
  const reasonBuffer = Buffer.isBuffer(reason) ? reason : Buffer.from(reason)
  const body = Buffer.allocUnsafe(2 + reasonBuffer.length)
  body.writeUInt16BE(code, 0)
  reasonBuffer.copy(body, 2)
  return body
}

describe('ByteParser', () => {
  describe('data frame parsing', () => {
    it('parses a complete text frame and emits its opcode and body', () => {
      const { parser, handler } = createParser()

      parser.write(makeFrame({
        opcode: opcodes.TEXT,
        payload: Buffer.from('hello')
      }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      const [type, data] = handler.onMessage.mock.calls[0]
      expect(type).toBe(opcodes.TEXT)
      expect(data.equals(Buffer.from('hello'))).toBe(true)
    })

    it('parses a binary frame, including zero bytes in the payload', () => {
      const payload = Buffer.from([0x00, 0xff, 0x10, 0x00])
      const { parser, handler } = createParser()

      parser.write(makeFrame({ opcode: opcodes.BINARY, payload }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      const [type, data] = handler.onMessage.mock.calls[0]
      expect(type).toBe(opcodes.BINARY)
      expect(data).toEqual(payload)
    })

    it('emits a zero-length text message', () => {
      const { parser, handler } = createParser()

      parser.write(makeFrame({ opcode: opcodes.TEXT }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      const [type, data] = handler.onMessage.mock.calls[0]
      expect(type).toBe(opcodes.TEXT)
      expect(data.length).toBe(0)
    })

    it('parses multiple consecutive frames from a single chunk', () => {
      const { parser, handler } = createParser()
      const chunk = Buffer.concat([
        makeFrame({ opcode: opcodes.TEXT, payload: Buffer.from('first') }),
        makeFrame({ opcode: opcodes.BINARY, payload: Buffer.from([1, 2, 3]) }),
        makeFrame({ opcode: opcodes.TEXT, payload: Buffer.from('third') })
      ])

      parser.write(chunk)

      expect(handler.onMessage).toHaveBeenCalledTimes(3)
      expect(handler.onMessage.mock.calls.map(([type]) => type)).toEqual([
        opcodes.TEXT,
        opcodes.BINARY,
        opcodes.TEXT
      ])
      expect(handler.onMessage.mock.calls.map(([, data]) => data.toString('hex'))).toEqual([
        Buffer.from('first').toString('hex'),
        '010203',
        Buffer.from('third').toString('hex')
      ])
    })

    it('waits for a frame to arrive across several writes', () => {
      const { parser, handler } = createParser()
      const frame = makeFrame({
        opcode: opcodes.TEXT,
        payload: Buffer.from('split payload')
      })

      parser.write(frame.subarray(0, 1))
      expect(handler.onMessage).not.toHaveBeenCalled()

      parser.write(frame.subarray(1, 2))
      expect(handler.onMessage).not.toHaveBeenCalled()

      parser.write(frame.subarray(2, 7))
      expect(handler.onMessage).not.toHaveBeenCalled()

      parser.write(frame.subarray(7))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('split payload')
    })

    it.each([
      ['inline-length maximum', 125],
      ['16-bit-length minimum', 126],
      ['64-bit-length minimum', 65536]
    ])('parses the %s payload boundary', (_, length) => {
      const payload = Buffer.alloc(length, 0x61)
      const { parser, handler } = createParser()

      parser.write(makeFrame({ opcode: opcodes.BINARY, payload }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      const [type, data] = handler.onMessage.mock.calls[0]
      expect(type).toBe(opcodes.BINARY)
      expect(data.length).toBe(length)
      expect(data[0]).toBe(0x61)
      expect(data[length - 1]).toBe(0x61)
    })
  })

  describe('fragmentation', () => {
    it('assembles a fragmented text message into one message', () => {
      const { parser, handler } = createParser()

      parser.write(makeFrame({
        opcode: opcodes.TEXT,
        payload: Buffer.from('hel'),
        fin: false
      }))
      expect(handler.onMessage).not.toHaveBeenCalled()

      parser.write(makeFrame({
        opcode: opcodes.CONTINUATION,
        payload: Buffer.from('lo')
      }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      const [type, data] = handler.onMessage.mock.calls[0]
      expect(type).toBe(opcodes.TEXT)
      expect(data.toString()).toBe('hello')
    })

    it('assembles multiple continuation frames and preserves empty fragments', () => {
      const { parser, handler } = createParser()

      parser.write(makeFrame({
        opcode: opcodes.BINARY,
        payload: Buffer.from([1]),
        fin: false
      }))
      parser.write(makeFrame({
        opcode: opcodes.CONTINUATION,
        payload: Buffer.alloc(0),
        fin: false
      }))
      parser.write(makeFrame({
        opcode: opcodes.CONTINUATION,
        payload: Buffer.from([2, 3])
      }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      const [type, data] = handler.onMessage.mock.calls[0]
      expect(type).toBe(opcodes.BINARY)
      expect(data).toEqual(Buffer.from([1, 2, 3]))
    })

    it('allows control frames between message fragments', () => {
      const { parser, handler, socket } = createParser()

      parser.write(makeFrame({
        opcode: opcodes.TEXT,
        payload: Buffer.from('hel'),
        fin: false
      }))
      parser.write(makeFrame({
        opcode: opcodes.PING,
        payload: Buffer.from('heartbeat')
      }))
      expect(handler.onPing).toHaveBeenCalledTimes(1)
      expect(handler.onMessage).not.toHaveBeenCalled()

      parser.write(makeFrame({
        opcode: opcodes.CONTINUATION,
        payload: Buffer.from('lo')
      }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('hello')
      expect(socket.writes).toHaveLength(1)
      expect(decodeFrame(socket.writes[0]).opcode).toBe(opcodes.PONG)
    })

    it('rejects a continuation frame when no fragmented message is in progress', () => {
      const { parser, handler } = createParser()

      parser.write(makeFrame({
        opcode: opcodes.CONTINUATION,
        payload: Buffer.from('unexpected')
      }))

      expect(handler.onMessage).not.toHaveBeenCalled()
      expectConnectionFailure(handler, 1002)
    })

    it('rejects a new data frame before a fragmented message is finished', () => {
      const { parser, handler } = createParser()

      parser.write(makeFrame({
        opcode: opcodes.TEXT,
        payload: Buffer.from('part'),
        fin: false
      }))
      parser.write(makeFrame({
        opcode: opcodes.TEXT,
        payload: Buffer.from('new message')
      }))

      expect(handler.onMessage).not.toHaveBeenCalled()
      expectConnectionFailure(handler, 1002)
    })

    it('rejects a fragmented control frame', () => {
      const { parser, handler } = createParser()

      parser.write(makeFrame({
        opcode: opcodes.PING,
        payload: Buffer.from('x'),
        fin: false
      }))

      expect(handler.onPing).not.toHaveBeenCalled()
      expectConnectionFailure(handler, 1002)
    })

    it('enforces the maximum number of message fragments', () => {
      const { parser, handler } = createParser({
        options: { maxFragments: 2 }
      })

      parser.write(makeFrame({
        opcode: opcodes.TEXT,
        payload: Buffer.from('a'),
        fin: false
      }))
      parser.write(makeFrame({
        opcode: opcodes.CONTINUATION,
        payload: Buffer.from('b'),
        fin: false
      }))
      parser.write(makeFrame({
        opcode: opcodes.CONTINUATION,
        payload: Buffer.from('c')
      }))

      expect(handler.onMessage).not.toHaveBeenCalled()
      expectConnectionFailure(handler, 1008)
    })
  })

  describe('payload limits', () => {
