      const { parser, handler } = createParser({
        options: { maxPayloadSize: 5 }
      })

      parser.write(makeFrame({
        opcode: opcodes.TEXT,
        payload: Buffer.from('12345')
      }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1].toString()).toBe('12345')
    })

    it('rejects a single frame larger than maxPayloadSize', () => {
      const { parser, handler } = createParser({
        options: { maxPayloadSize: 4 }
      })

      parser.write(makeFrame({
        opcode: opcodes.TEXT,
        payload: Buffer.from('12345')
      }))

      expect(handler.onMessage).not.toHaveBeenCalled()
      expectConnectionFailure(handler, 1009)
    })

    it('enforces maxPayloadSize against the cumulative size of fragments', () => {
      const { parser, handler } = createParser({
        options: { maxPayloadSize: 5 }
      })

      parser.write(makeFrame({
        opcode: opcodes.TEXT,
        payload: Buffer.from('123'),
        fin: false
      }))
      parser.write(makeFrame({
        opcode: opcodes.CONTINUATION,
        payload: Buffer.from('456')
      }))

      expect(handler.onMessage).not.toHaveBeenCalled()
      expectConnectionFailure(handler, 1009)
    })

    it('does not apply maxPayloadSize to control frames', () => {
      const { parser, handler, socket } = createParser({
        options: { maxPayloadSize: 1 }
      })

      parser.write(makeFrame({
        opcode: opcodes.PING,
        payload: Buffer.from('ping payload')
      }))

      expect(handler.onPing).toHaveBeenCalledTimes(1)
      expect(handler.onPing.mock.calls[0][0].toString()).toBe('ping payload')
      expect(socket.writes).toHaveLength(1)
      expect(decodeFrame(socket.writes[0]).body.toString()).toBe('ping payload')
    })

    it('treats maxPayloadSize of zero as disabling the limit', () => {
      const { parser, handler } = createParser({
        options: { maxPayloadSize: 0 }
      })
      const payload = Buffer.alloc(1024, 0x62)

      parser.write(makeFrame({ opcode: opcodes.BINARY, payload }))

      expect(handler.onMessage).toHaveBeenCalledTimes(1)
      expect(handler.onMessage.mock.calls[0][1]).toEqual(payload)
    })

    it.each([
