      ['length is greater than 2^31 - 1', Buffer.from([0x82, 0x7f, 0, 0, 0, 0, 0x80, 0, 0, 0])]
    ])('rejects a 64-bit payload length when the %s', (_, frame) => {
      const { parser, handler } = createParser()

