    })

    it('rejects a control frame with a payload greater than 125 bytes', () => {
      const { parser, handler } = createParser()

      parser.write(makeFrame({
        opcode: opcodes.CLOSE,
        payload: Buffer.alloc(126, 0x61)
      }))

      expectConnectionFailure(handler, 1002)
    })

    it('pauses parsing while a control-frame response experiences backpressure', () => {
      const { parser, handler, socket } = createParser()
      socket.writableNeedDrain = true

