      parser.write(makeFrame({
        opcode: 0x03,
        payload: Buffer.from('x')
      }))

      expect(handler.onMessage).not.toHaveBeenCalled()
      expectConnectionFailure(handler, 1002)
    })

    it('rejects a masked server-to-client frame', () => {
      const { parser, handler } = createParser()

      parser.write(makeFrame({
        opcode: opcodes.TEXT,
        payload: Buffer.from('masked'),
        masked: true
      }))

      expect(handler.onMessage).not.toHaveBeenCalled()
      expectConnectionFailure(handler, 1002)
    })

    it.each([
      ['RSV1 without a negotiated extension', { rsv1: true }],
      ['RSV2', { rsv2: true }],
      ['RSV3', { rsv3: true }]
    ])('rejects %s', (_, reservedBits) => {
      const { parser, handler } = createParser()

      parser.write(makeFrame({
        opcode: opcodes.TEXT,
        payload: Buffer.from('x'),
