    })

    it('decompresses a message when RSV1 is set', async () => {
      const { parser, handler } = createParser({
        extensions: new Map([['permessage-deflate', '']])
      })
      const expected = Buffer.from('compressed hello')
      const compressed = zlib.deflateRawSync(expected, {
        finishFlush: zlib.constants.Z_SYNC_FLUSH
