    it('returns an empty buffer for consume(0) and throws for an over-consumption', () => {
      const { parser } = createParser()

      const empty = parser.consume(0)
      expect(empty.length).toBe(0)
      expect(() => parser.consume(1)).toThrow('Called consume() before buffers satiated.')
    })

    it('consumes bytes spanning multiple buffered chunks', () => {
      const { parser, handler } = createParser()
      const frame = makeFrame({
